#define DT_DRV_COMPAT zephyr_i2c_emul_controller

#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/device.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(i2c_emul, CONFIG_I2C_EMUL_LOG_LEVEL);

struct i2c_emul_data {
	const struct device *i2c_dev;
	struct i2c_emul *emuls;
	size_t emuls_len;
	struct k_mutex mutex;
};

static int i2c_emul_transfer(const struct device *dev, struct i2c_msg *msgs,
			     uint8_t num_msgs, uint16_t addr)
{
	struct i2c_emul_data *data = dev->data;
	int rc = -EIO;

	k_mutex_lock(&data->mutex, K_FOREVER);

	for (size_t i = 0; i < data->emuls_len; i++) {
		if (data->emuls[i].addr == addr) {
			rc = data->emuls[i].api->transfer(data->emuls[i].target_dev,
						  msgs, num_msgs, addr);
			break;
		}
	}

	k_mutex_unlock(&data->mutex);

	return rc;
}

static int i2c_emul_get_config(const struct device *dev, uint32_t *config)
{
	*config = I2C_MODE_MASTER | I2C_SPEED_SET(I2C_SPEED_STANDARD);
	return 0;
}

static int i2c_emul_init(const struct device *dev)
{
	struct i2c_emul_data *data = dev->data;

	k_mutex_init(&data->mutex);

	return 0;
}

#ifdef CONFIG_PM_DEVICE
static int i2c_emul_pm_control(const struct device *dev,
				enum pm_device_action action)
{
	ARG_UNUSED(dev);
	ARG_UNUSED(action);
	return 0;
}
#define I2C_EMUL_PM_CONTROL_FN i2c_emul_pm_control
#else
#define I2C_EMUL_PM_CONTROL_FN NULL
#endif

static const struct i2c_driver_api i2c_emul_api = {
	.transfer = i2c_emul_transfer,
	.get_config = i2c_emul_get_config,
};

#define I2C_EMUL_DEFINE(n)                                                     \
	static struct i2c_emul i2c_emul_##n[] = {                              \
		DT_INST_FOREACH_CHILD_STATUS_OKAY_VARGS(n, I2C_EMUL_TARGET_DEFINE, \
							DT_DRV_INST(n))                \
	};                                                                     \
	static struct i2c_emul_data i2c_emul_data_##n = {                      \
		.i2c_dev = DEVICE_DT_INST_GET(n),                              \
		.emuls = i2c_emul_##n,                                         \
		.emuls_len = ARRAY_SIZE(i2c_emul_##n),                         \
	};                                                                     \
	DEVICE_DT_INST_DEFINE(n, i2c_emul_init, I2C_EMUL_PM_CONTROL_FN,        \
			      &i2c_emul_data_##n, NULL,                          \
			      POST_KERNEL, CONFIG_I2C_EMUL_INIT_PRIORITY,          \
			      &i2c_emul_api);

DT_INST_FOREACH_STATUS_OKAY(I2C_EMUL_DEFINE)
